<?php
namespace App\Http\Controllers\Public\Business\Admin\Ecommerce\OnlineOrders\OnlineOrderList;
use App\Http\Controllers\Controller;
use App\Services\Public\Business\Admin\Authorization\AccessControl\Access;
use App\Services\Public\Business\Admin\Ecommerce\OnlineOrders\OnlineOrderList\OnlineOrderService;
use Illuminate\Http\Request;
class OnlineOrderController extends Controller {
 public function index(Request $r,Access $a,OnlineOrderService $s){ $v=$a->check($r,'ecommerce','online-orders','online-order-list');$q=$s->query($v['business']);$v['stats']=['all'=>(clone $q)->count(),'pending'=>(clone $q)->where('status','confirmed')->where('delivery_status','pending')->count(),'shipped'=>(clone $q)->where('status','confirmed')->where('delivery_status','shipped')->count(),'delivered'=>(clone $q)->where('delivery_status','delivered')->count()];if($r->filled('q'))$q->where(fn($x)=>$x->where('order_no','like','%'.mb_substr($r->query('q'),0,80).'%')->orWhere('customer_name','like','%'.mb_substr($r->query('q'),0,80).'%'));if(in_array($r->query('delivery'),['pending','packed','shipped','delivered'],true))$q->where('delivery_status',$r->query('delivery'));$dates=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d']);if(!empty($dates['from']))$q->whereDate('created_at','>=',$dates['from']);if(!empty($dates['to']))$q->whereDate('created_at','<=',$dates['to']);$v['orders']=$q->latest('id')->paginate(20)->withQueryString();$v['title']=t('Online orders','অনলাইন অর্ডার');return view('public.business.admin.ecommerce.online-orders.index',$v); }
 public function show(Request $r,string $business,int $order,Access $a,OnlineOrderService $s){ $v=$a->check($r,'ecommerce','online-orders','online-order-list');$v['order']=$s->query($v['business'])->with(['items'=>fn($q)=>$q->where('business_id',$v['business']->id)])->findOrFail($order);$v['cancellations']=\App\Models\Ecommerce\CancellationRequest::where('business_id',$v['business']->id)->where('order_id',$v['order']->id)->latest('id')->get();$v['title']=t('Order details','অর্ডারের বিবরণ');return view('public.business.admin.ecommerce.online-orders.show',$v); }
 public function reviewCancellation(Request $r,string $business,int $record,Access $a,\App\Services\Public\Business\Admin\Ecommerce\OnlineOrders\OnlineOrderList\CancellationRequestService $service,\App\Services\Public\Business\Admin\Sales\Orders\OrderDetails\CancelSale $cancel){$v=$a->check($r,'ecommerce','online-orders','online-order-list','update');$data=$r->validate(['decision'=>'required|in:approved,rejected','admin_note'=>'required_if:decision,rejected|nullable|string|max:255']);if($data['decision']==='approved')$a->check($r,'sales','orders','order-details','delete');$service->review($v['business'],$record,$v['user']->id,$data,$cancel);return back()->with('success',t('Cancellation reviewed.','বাতিলের অনুরোধ পর্যালোচিত হয়েছে।'));}
}
